There exists $q>2$ depending only on $d$, $m$, and $M$ such that for any $p\in[1,\infty)$ and any $\gamma$ and $\gamma_0$ belonging to $\Gamma'$, it holds that
	\begin{align}
		\left\lVert \kappa_\gamma-\kappa_{\gamma_0} \right\rVert_{L^2(\partial\Omega\times\partial\Omega)}\leq C\left\lVert \gamma-\gamma_0 \right\rVert_{L^p(\Omega)}^{\frac12\min\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(1, \frac{p}{q}\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)}\,.
	\end{align}
	The constant $C>0$ depends on $d$, $p$, $q$, $m$, $M$, $\Omega$, and $\Omega'$.

If $d\geq 2$ and $R>0$, then there exists a constant $C^\star>0$ such that for any $\gamma\in\mathcal{X}_d(R)$ and any $\gamma_0\in\mathcal{X}_d(R)$, it holds that
    \begin{align}
        \left\lVert \Psi^\star(\kappa_\gamma)-\Psi^\star(\kappa_{\gamma_0}) \right\rVert_{L^2(\Omega)}\leq C^\star \omega^\star\bigl(\left\lVert \kappa_{\gamma}-\kappa_{\gamma_0} \right\rVert_{L^2(\partial\Omega\times{\partial\Omega})}\bigr)\,,
    \end{align}
    where $t\mapsto \omega^\star(t)\coloneqq \omega(\sqrt{t})$ and $\omega$ is as in (3.3).

For any real numbers $s$ and $t$, there exists $C>0$ depending on $d$, $s$, $t$, $\Omega$, $\Omega'$, $m$, and $M$ such that for all $\gamma$ and $\gamma_0$ belonging to $\Gamma'$, it holds that
    \begin{align}
        \left\lVert \mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0} \right\rVert_{\mathscr{L}(H^{-1/2}_\diamond({\partial\Omega});H_{\phantom{\diamond}}^{1/2}({\partial\Omega})/\mathbb{C})}\leq C\left\lVert \mathscr{R}_{\gamma}-\mathscr{R}_{\gamma_0} \right\rVert^{1/2}_{\mathrm{HS}(H^{s}_\diamond({\partial\Omega});H^{t}({\partial\Omega})/\mathbb{C})}\,.
    \end{align}

Let $\Psi^\star\colon\mathrm{Dom}(\Psi^\star)\subseteq L^2({\partial\Omega}\times{\partial\Omega})\to L^2(\Omega)$ be as in (3.9) and (3.10). Let $C^\star$ and $\omega^\star$ be as in 3.8. There exists $\widetilde{\Psi}^\star\colon L^2({\partial\Omega}\times{\partial\Omega})\to L^2(\Omega)$ such that $\widetilde{\Psi}^\star(\kappa)=\Psi^\star(\kappa)$ for all $\kappa\in\mathrm{Dom}(\Psi^\star)$, and
    \begin{align}
        \left\lVert \widetilde{\Psi}^\star(\kappa)-\widetilde{\Psi}^\star(\kappa_0) \right\rVert_{L^2(\Omega)}\leq C^\star \omega^\star\bigl(\left\lVert \kappa-\kappa_0 \right\rVert_{L^2(\partial\Omega\times{\partial\Omega})}\bigr)
    \end{align}
    for all $\kappa\in L^2({\partial\Omega}\times{\partial\Omega})$ and all $\kappa_0\in L^2({\partial\Omega}\times{\partial\Omega})$.

Suppose that 2 holds. Let $C^\star$ and $\omega^\star$ be as in 3.8. Let $d\geq 2$ and $R>0$. For any compact set  $K \subset L^2({\partial\Omega}\times{\partial\Omega})$ and any $\delta>0$, the following holds. Let $K_\delta\coloneqq{\{\eta\in K\colon \left\lVert \eta \right\rVert_{L^2({\partial\Omega}\times{\partial\Omega})}\leq \delta\}}$. For any $\varepsilon>0$, there exists a generalized FNO $\Psi \colon L^2({\partial\Omega}\times{\partial\Omega})\to L^2(\Omega)$ of the form (4.15) such that
    \begin{align}
        \sup_{(\gamma,\eta)\in \mathcal{X}_d(R)\times K_\delta} \left\lVert \gamma - \Psi(\kappa_\gamma + \eta) \right\rVert_{L^2(\Omega)} \leq  \varepsilon + C^\star\omega^\star(\delta)\,.
    \end{align}
